insert into public.regions (id, slug, name, country, image, blurb) values
  ('r-malaga', 'malaga', 'Málaga', 'Spain', 'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?auto=format&fit=crop&w=1200&q=70', 'City living, universities and the port. Strong demand for 1 to 6 month stays.'),
  ('r-torremolinos-benalmadena', 'torremolinos-benalmadena', 'Torremolinos & Benalmádena', 'Spain', 'https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?auto=format&fit=crop&w=1200&q=70', 'Beachfront apartments close to the airport, popular with winter guests.'),
  ('r-fuengirola-mijas', 'fuengirola-mijas', 'Fuengirola & Mijas', 'Spain', 'https://images.unsplash.com/photo-1493809842364-78817add7ffb?auto=format&fit=crop&w=1200&q=70', 'Family-friendly coast with international schools and long promenades.'),
  ('r-marbella', 'marbella', 'Marbella', 'Spain', 'https://images.unsplash.com/photo-1613490493576-7fde63acd811?auto=format&fit=crop&w=1200&q=70', 'Golden Mile, Puerto Banús and Nueva Andalucía. Premium long stays.'),
  ('r-benahavis', 'benahavis', 'Benahavís', 'Spain', 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=1200&q=70', 'Villas in the hills, golf and privacy, 10 minutes from the coast.'),
  ('r-estepona', 'estepona', 'Estepona', 'Spain', 'https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1200&q=70', 'Old town charm and new beachfront developments.'),
  ('r-manilva-sotogrande', 'manilva-sotogrande', 'Manilva & Sotogrande', 'Spain', 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1200&q=70', 'Marinas, polo and golf on the western Costa del Sol.'),
  ('r-nerja-axarquia', 'nerja-axarquia', 'Nerja & Axarquía', 'Spain', 'https://images.unsplash.com/photo-1564013799919-ab600027ffc6?auto=format&fit=crop&w=1200&q=70', 'Whitewashed villages and quiet coves east of Málaga.');
