insert into public.properties (id, slug, organization_id, region_id, title, city, area, type, size_m2, bedrooms, bathrooms, max_guests, min_months, max_months, monthly_price, utilities_included, agent_commission_pct, description, amenities, photos, visibility, status, listed_on, lat, lng, listing_source, external_id, mirror_content, price_mode, source_nightly_rate, source_monthly_rate, calendar_type, ical_url, pms_provider, pms_listing_id, sync_status) values
  ('p1', 'sea-view-penthouse-golden-mile-p1', 'o-cqre', 'r-marbella', 'Sea-view penthouse, Golden Mile', 'Marbella', 'Golden Mile', 'apartment', 140, 3, 2, 6, 1, 6, 4800, true, 10, 'Bright penthouse with wraparound terrace and open sea views, 5 minutes walk to the beach. Ideal for families spending the winter on the coast.', array['Wi-Fi','Sea view','Terrace','Pool','Air conditioning','Parking','Bed linens','Fully equipped kitchen','Workspace']::text[], array['https://images.unsplash.com/photo-1613490493576-7fde63acd811?auto=format&fit=crop&w=1200&q=70','https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1200&q=70','https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1200&q=70']::text[], 'public', 'published', array['airbnb','booking']::text[], 36.5068, -4.9156, 'guesty', 'gst-6512a1', true, 'own', 210, 5400, 'pms', null, 'guesty', 'gst-6512a1', 'ok'),
