  ('p3', 'soho-family-flat-near-the-port-p3', 'o-cqre', 'r-malaga', 'Soho family flat near the port', 'Málaga', 'Soho', 'apartment', 100, 4, 2, 7, 2, 6, null, true, 10, 'Spacious four-bedroom flat in Soho with balcony, close to the port and museums.', array['Wi-Fi','Workspace','Washing machine','Dishwasher','Air conditioning','Elevator','Bed linens','Fully equipped kitchen']::text[], array['https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?auto=format&fit=crop&w=1200&q=70','https://images.unsplash.com/photo-1493809842364-78817add7ffb?auto=format&fit=crop&w=1200&q=70']::text[], 'public', 'published', array['airbnb']::text[], 36.7175, -4.426, 'guesty', 'gst-90ab33', true, 'own', 120, null, 'pms', null, 'guesty', 'gst-90ab33', 'ok'),
