  ('p11', 'cliff-top-house-above-burriana-beach-p11', 'o-priv1', 'r-nerja-axarquia', 'Cliff-top house above Burriana beach', 'Nerja', null, 'house', 150, 3, 2, 6, 2, 6, 2400, true, null, 'Andalusian house with sea-view terrace and plunge pool, walking distance to the Balcón de Europa.', array['Wi-Fi','Sea view','Terrace','Pool','Parking','Fully equipped kitchen']::text[], array['https://images.unsplash.com/photo-1564013799919-ab600027ffc6?auto=format&fit=crop&w=1200&q=70','https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1200&q=70']::text[], 'public', 'published', array['airbnb']::text[], 36.748, -3.864, 'manual', null, true, 'own', null, null, 'ical', 'https://www.airbnb.com/calendar/ical/123.ics', null, null, 'ok'),
